import org.junit.jupiter.params.provider.ValueSource;

class LmdbBlankNodePreCacheReservationTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final String FIXED = "pre-cache-0";
	private static final IRI P = VF.createIRI("urn:reservation:p");
	private static final IRI Q = VF.createIRI("urn:reservation:q");
	private static final String BODY = "?s <urn:reservation:p> ?o . ?s <urn:reservation:q> ?other . ";

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void originalFixedIdentityIsReservedBeforeColdOrHotNativeOptimization(boolean hot, @TempDir Path directory)
			throws Exception {
		LmdbStore store = initializedStore(directory);
		try (SailDataset dataset = store.getBackingStore()
				.getExplicitSailSource()
				.dataset(IsolationLevels.SNAPSHOT_READ)) {
			ValueStore dictionary = (ValueStore) store.getValueFactory();
			assertEquals(LmdbValue.UNKNOWN_ID, dictionary.getId(VF.createBNode(FIXED), false));
			SailDatasetTripleTermSource source = new SailDatasetTripleTermSource(store.getValueFactory(), dataset);
			EvaluationStatistics statistics = store.getBackingStore().getEvaluationStatistics();
			if (hot) {
				try (var ignored = new BlankNodeAllocationScope("warming-", id -> false).activate()) {
					EvaluationStrategy strategy = store.getEvaluationStrategyFactory()
							.createEvaluationStrategy(null, source, statistics);
					strategy.optimize(expression(false, false), statistics, EmptyBindingSet.getInstance());
				}
			}
			BlankNodeAllocationScope scope = new BlankNodeAllocationScope("pre-cache-", id -> false);
			try (var ignored = scope.activate()) {
				EvaluationStrategy strategy = store.getEvaluationStrategyFactory()
						.createEvaluationStrategy(null, source, statistics);
				TupleExpr original = expression(false, false);
				assertEquals(Set.of(FIXED), LocalBNodeReferences.collect(original));
				TupleExpr optimized = strategy.optimize(original, statistics, EmptyBindingSet.getInstance());
				assertFalse(LocalBNodeReferences.collect(optimized).contains(FIXED),
						"the actual optimizer must remove the now-true fixed-reference condition");
				assertEquals(hot,
						Boolean.parseBoolean(optimized.getStringMetricPlanned("optimizer.pipelinePlanCacheHit")),
						"the hot control must execute a genuine native pipeline-cache hit");
				assertNotEquals(FIXED, scope.createBNode(store.getValueFactory()).getID(),
						"original occupied identities must be reserved before optimization or cache lookup");
			}
			assertEquals(LmdbValue.UNKNOWN_ID, dictionary.getId(VF.createBNode(FIXED), false));
		} finally {
			store.shutDown();
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void directSailExecutionCannotAllocateAnEliminatedFixedIdentity(boolean nested, @TempDir Path directory) {
		LmdbStore store = initializedStore(directory);
		try (var connection = store.getConnection();
				var ignored = new BlankNodeAllocationScope("pre-cache-", id -> false).activate();
				var rows = connection.evaluate(expression(true, nested), null, EmptyBindingSet.getInstance(), false)) {
			assertTrue(rows.hasNext());
			assertNotEquals(FIXED, rows.next().getValue("fresh").stringValue(),
					"direct Sail execution retains the same original-reference freshness contract");
			assertFalse(rows.hasNext());
		} finally {
			store.shutDown();
		}
	}

	@Test
	void ordinaryRepositoryPreflightRetainsTheFixedReferenceContract(@TempDir Path directory) {
		SailRepository repository = new SailRepository(new LmdbStore(directory.toFile()));
		repository.init();
		try (var connection = repository.getConnection()) {
			seed((LmdbStoreConnection) connection.getSailConnection());
			var query = connection.prepareTupleQuery("SELECT (BNODE() AS ?fresh) WHERE { " + BODY
					+ "FILTER(sameTerm(<_:" + FIXED + ">, <_:" + FIXED + ">)) }");
			try (var rows = query.evaluate()) {
				assertTrue(rows.hasNext());
				assertNotEquals(FIXED, rows.next().getValue("fresh").stringValue());
				assertFalse(rows.hasNext());
			}
		} finally {
			repository.shutDown();
		}
	}

	private static TupleExpr expression(boolean allocate, boolean nested) {
		String fixed = nested ? "<<( <_:" + FIXED + "> <urn:reservation:embedded> <urn:reservation:object> )>>"
				: "<_:" + FIXED + ">";
		return QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL,
				"SELECT " + (allocate ? "(BNODE() AS ?fresh)" : "?s") + " WHERE { " + BODY
						+ "FILTER(sameTerm(" + fixed + ", " + fixed + ")) }",
				null).getTupleExpr();
	}

	private static LmdbStore initializedStore(Path directory) {
		LmdbStore store = new LmdbStore(directory.toFile());
		store.init();
		try (LmdbStoreConnection connection = (LmdbStoreConnection) store.getConnection()) {
			seed(connection);
		}
		return store;
	}

	private static void seed(LmdbStoreConnection connection) {
		connection.begin();
		connection.addStatement(VF.createIRI("urn:reservation:s"), P, VF.createLiteral("left"));
		connection.addStatement(VF.createIRI("urn:reservation:s"), Q, VF.createLiteral("right"));
		connection.commit();
	}
}
